import{_ as a,o as i,c as s,a2 as n}from"./chunks/framework.BTLSZHNB.js";const m=JSON.parse('{"title":"0009 — Form Families and namespaced API groups","description":"","frontmatter":{},"headers":[],"relativePath":"spec/decisions/0009-form-families-and-namespaced-api-versions.md","filePath":"spec/decisions/0009-form-families-and-namespaced-api-versions.md"}'),t={name:"spec/decisions/0009-form-families-and-namespaced-api-versions.md"};function o(r,e,l,d,p,c){return i(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="_0009-—-form-families-and-namespaced-api-groups" tabindex="-1">0009 — Form Families and namespaced API groups <a class="header-anchor" href="#_0009-—-form-families-and-namespaced-api-groups" aria-label="Permalink to &quot;0009 — Form Families and namespaced API groups&quot;">​</a></h1><ul><li>Status: accepted</li><li>Date: 2026-08-06</li><li>Owners: Takoform maintainers</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Every current FormRef carries the single central group <code>forms.takoform.com/v1alpha2</code>. Decision <a href="./0008-forms-preserve-service-shape.html">0008</a> multiplies the number of Forms: one shape per proven service primitive, plus revision, deployment, attachment, and policy resources around each identity. A single flat namespace cannot carry many coherent product families, third-party Forms, or independent family evolution without renumbering the whole epoch.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Forms are organized into <strong>Form Families</strong>: named groups of Forms that share a platform model and are designed to compose. A family is a catalog grouping and an API namespace; it is not a package unit. The existing trust boundary — one Form Package contains exactly one Form Definition — is retained.</p><p>The FormRef <code>apiVersion</code> becomes a DNS-like group with its own version:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;apiVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;edge.forms.takoform.com/v1alpha1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;kind&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ModuleWorker&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;definitionVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.1.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;schemaDigest&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sha256:...&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Validation accepts <code>&lt;dns-like group&gt;/&lt;version&gt;</code> rather than one fixed constant. Third-party groups such as <code>forms.example.com/v1alpha1</code> are valid FormRefs; trust in a publisher remains a separate policy fact and never enters the FormRef.</p><p>The first official family is the <strong>Edge Platform Family</strong>, <code>edge.forms.takoform.com/v1alpha1</code>: Module Workers with versions, deployments, routes, domains and cron triggers; edge KV; object buckets; SQLite databases; at-least-once queues with consumers; dense vector indexes. Container platform, managed database, and eventing families are separate groups defined later.</p><p>Every current Form Definition declares a <code>role</code> from a closed enum:</p><ul><li><code>identity</code> — long-lived logical resource;</li><li><code>revision</code> — immutable implementation snapshot; update is forbidden;</li><li><code>deployment</code> — selects which revisions are active;</li><li><code>attachment</code> — connects a parent resource to external events or endpoints;</li><li><code>policy</code> — configuration changed independently of the parent.</li></ul><p>Tooling enforces role rules mechanically: revisions are never updated in place, deleting an attachment never deletes its parent, and policy state never migrates into the parent identity.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li><code>forms.takoform.com/v1alpha2</code> remains the retained provider-v2 group; new families never reuse it.</li><li>FormRef parsing, package verification, registries, and the provider accept namespaced groups and can carry multiple exact FormRefs for one kind name in different groups.</li><li>Catalog and docs generation group by family.</li><li>Publisher identity, package digest, and host support remain separate facts from the FormRef, exactly as before.</li></ul><h2 id="rejected-alternatives" tabindex="-1">Rejected alternatives <a class="header-anchor" href="#rejected-alternatives" aria-label="Permalink to &quot;Rejected alternatives&quot;">​</a></h2><ul><li><strong>Keep one central group and encode the family in the kind name.</strong> Rejected because it renumbers every Form whenever any family evolves and prevents third-party groups entirely.</li><li><strong>One package per family.</strong> Rejected because it widens the audited trust boundary; per-Form packages keep review, digesting, and revocation exact.</li><li><strong>Encode the publisher in the FormRef.</strong> Rejected because semantic identity and distribution trust must stay independently verifiable; a publisher change must not re-identify semantics.</li></ul>`,17)])])}const u=a(t,[["render",o]]);export{m as __pageData,u as default};
